/**
 * @file Monster skill lists and skill timing, generated by
 * `scripts/extract_monster_skill_timing.py` from the client tables.
 *
 * - `MonsterSkillIds.json`: the skills a monster template can cast
 *   (MonsterTable.SkillIds; 96% of real casts in captured logs).
 * - `MonsterSkillTiming.json`: cooldown, battle-start window, sing time and
 *   danger flag per skill. The cooldown is a lower bound: monsters never
 *   recast sooner, but the AI may wait longer.
 */
import monsterSkillIdsData from "./MonsterSkillIds.json";
import monsterSkillTimingData from "./MonsterSkillTiming.json";

export type MonsterSkillTiming = {
  /** Seconds between two casts of one monster; `0` when unknown. */
  cooldownSeconds: number;
  /**
   * Window of the first cast after the monster enters combat, in seconds;
   * `"never"` when the skill is not cast at battle start, `null` when the
   * table gives no window.
   */
  battleStart: readonly [number, number] | "never" | null;
  /** Sing/guide bar duration; `0` for an instant skill. */
  singSeconds: number;
  /** Marked dangerous, or shown with the game's danger cast bar. */
  danger: boolean;
};

type RawTiming = {
  cd?: number;
  start?: number[] | "never";
  sing?: number;
  /** 1 monster bar, 2 danger bar, 3 steel bar. */
  bar?: number;
  danger?: boolean;
};

const RAW_SKILL_IDS = monsterSkillIdsData as Record<string, number[]>;
const RAW_TIMING = monsterSkillTimingData as Record<string, RawTiming>;
const DANGER_BAR = 2;
const NO_SKILLS: readonly number[] = [];
const timingCache = new Map<number, MonsterSkillTiming>();

function positive(value: unknown): number {
  return typeof value === "number" && Number.isFinite(value) && value > 0
    ? value
    : 0;
}

/** The skills `monsterId` can cast, ascending; empty when unknown. */
export function monsterSkillIdsOf(
  monsterId: number | null | undefined,
): readonly number[] {
  if (monsterId === null || monsterId === undefined) return NO_SKILLS;
  return RAW_SKILL_IDS[String(monsterId)] ?? NO_SKILLS;
}

export function monsterSkillTiming(skillId: number): MonsterSkillTiming {
  const cached = timingCache.get(skillId);
  if (cached) return cached;
  const raw = RAW_TIMING[String(skillId)] ?? {};
  const start = raw.start;
  const timing: MonsterSkillTiming = {
    cooldownSeconds: positive(raw.cd),
    battleStart:
      start === "never"
        ? "never"
        : Array.isArray(start) && start.length === 2
          ? [positive(start[0]), positive(start[1])]
          : null,
    singSeconds: positive(raw.sing),
    danger: raw.danger === true || raw.bar === DANGER_BAR,
  };
  timingCache.set(skillId, timing);
  return timing;
}
